// Failed runs must never be silent. Replace with Slack/Email/PagerDuty in production.
const e = $input.first().json;
console.error(`[ALERT] Workflow "${e.workflow?.name}" failed at node "${e.execution?.lastNodeExecuted}": ${e.execution?.error?.message} (execution ${e.execution?.id})`);
return [{ json: { alerted: true, workflow: e.workflow?.name, error: e.execution?.error?.message } }];
